import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"data is a nominal former + constructor arrows + dependent eliminator","description":"","frontmatter":{"title":"`data` is a nominal former + constructor arrows + dependent eliminator","type":"adr","date":"2026-10-21T00:00:00.000Z","status":"accepted","applies_to":"`kernel` (`handl-value`), `kit-prelude-lang` (grammar, desugar"},"headers":[],"relativePath":"handl/project/adrs/0152-data-nominal-inductive-families.md","filePath":"vendored/handl/project/adrs/0152-data-nominal-inductive-families.md"}'),a={name:`handl/project/adrs/0152-data-nominal-inductive-families.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0152-data-is-a-nominal-former-constructor-arrows-dependent-eliminator" tabindex="-1">ADR-0152: <code>data</code> is a nominal former + constructor arrows + dependent eliminator <a class="header-anchor" href="#adr-0152-data-is-a-nominal-former-constructor-arrows-dependent-eliminator" aria-label="Permalink to “ADR-0152: data is a nominal former + constructor arrows + dependent eliminator”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>data F(i₁…iₖ : I₁…Iₖ) :: C₁ : S₁ | … | Cₙ : Sₙ</code> elaborates into three declarations in the ordinary object/arrow world. All three are values and types of the kind ADR-0106 already defines — no new machinery.</p><h3 id="_1-f-is-a-nominal-former" tabindex="-1">1. <code>F</code> is a nominal former <a class="header-anchor" href="#_1-f-is-a-nominal-former" aria-label="Permalink to “1. F is a nominal former”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>F : Pi(i₁ : I₁, …, Pi(iₖ : Iₖ, Type))</span></span></code></pre></div><p><code>F</code> binds a <code>sym</code> nominal (the former&#39;s identity). Applying it does <strong>not</strong> mint a fresh <code>sym</code> per call — it produces the canonical <em>family-application</em> object:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Vec(2, Int)  ==  { &quot;__former__&quot;: vecSym, &quot;indices&quot;: [2, Int] }</span></span></code></pre></div><p>Family equality is then ordinary: same former identity + index equality. <code>Vec ≠ List</code> because <code>vecSym ≠ listSym</code> (nominal); <code>Vec(2, Int) == Vec(2, Int)</code> because the applications are equal data. This also resolves the generic-instantiation memoization question left open in ADR-0106 §9 (<code>List&lt;Int&gt; == List&lt;Int&gt;</code>): a family application is canonical data, not a per-call symbol mint.</p><h3 id="_2-each-constructor-is-a-nominal-arrow-into-the-family" tabindex="-1">2. Each constructor is a nominal arrow into the family <a class="header-anchor" href="#_2-each-constructor-is-a-nominal-arrow-into-the-family" aria-label="Permalink to “2. Each constructor is a nominal arrow into the family”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Cⱼ : Pi(x₁ : A₁, …, xₘ : Aₘ, F(j₁…jₖ))</span></span></code></pre></div><p><code>Cⱼ</code> binds a <code>sym</code> (the constructor&#39;s nominal identity — <code>match</code> dispatches on <em>identity</em>, not on a <code>{&quot;tag&quot;}</code> string). Application produces a tagged object carrying the ctor sym and the field values:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Succ(Zero)  ==  { &quot;__ctor__&quot;: succSym, &quot;pred&quot;: Zero }</span></span></code></pre></div><p>Membership is <em>declared</em>: <code>type_of(Cⱼ(…))</code> is <code>F(j⃗)</code> by the ctor&#39;s result type — no tag inspection, no chain walk. <code>Succ(3)</code> fails to check because <code>3 : Nat</code> fails; <code>Succ(Zero)</code> checks and yields <code>Nat</code>.</p><h3 id="_3-f-rec-is-the-dependent-eliminator" tabindex="-1">3. <code>F.rec</code> is the dependent eliminator <a class="header-anchor" href="#_3-f-rec-is-the-dependent-eliminator" aria-label="Permalink to “3. F.rec is the dependent eliminator”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>F.rec : Pi(m    : Pi(i⃗ : I⃗, F(i⃗) ~&gt; Type),          -- the motive</span></span>
<span class="line"><span>          Pi(c₁ : S₁[rec], …,                       -- one case per ctor</span></span>
<span class="line"><span>          Pi(cₙ : Sₙ[rec],</span></span>
<span class="line"><span>          Pi(i⃗ : I⃗, Pi(v : F(i⃗), m(i⃗, v))))))</span></span></code></pre></div><p>where <code>Sⱼ[rec]</code> is <code>Cⱼ</code>&#39;s signature with a <code>Pi(x_rec, m(…, field))</code> argument inserted after each recursive field. For <code>Nat</code>:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Nat.rec : Pi(m   : Nat ~&gt; Type,</span></span>
<span class="line"><span>            Pi(cZ : m(Zero),</span></span>
<span class="line"><span>            Pi(cS : Pi(p : Nat, m(p) ~&gt; m(Succ p)),</span></span>
<span class="line"><span>            Pi(n : Nat, m(n)))))</span></span></code></pre></div><p>It <strong>computes</strong> — iota reduction is definitional:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Nat.rec(m, cZ, cS, Zero)    ⟶  cZ</span></span>
<span class="line"><span>Nat.rec(m, cZ, cS, Succ p)  ⟶  cS(p, Nat.rec(m, cZ, cS, p))</span></span></code></pre></div><p><code>match</code> is surface sugar: <code>match v { Zero: z, Succ(p): s p }</code> lowers to <code>Nat.rec((n) ~&gt; &lt;result type&gt;, z, (p, ih) ~&gt; s p, v)</code> — and the dependent reading (motive <code>m</code> may use the scrutinee <code>n</code>) is what per-arm index refinement already implements in <code>synth_match_arms</code>: the refinement is no longer a checker special-case, it is the type of <code>F.rec</code>&#39;s cases. <code>absurd</code> remains: an arm is inhabited only if its refined index equations are satisfiable.</p><p>Iota is also where index equality comes from: <code>Vec(1+1)</code> ≡ <code>Vec(2)</code> because <code>1+1</code> <em>evaluates</em> to <code>2</code> under the shared evaluator — the bespoke index-rewriting solver becomes a normalization question, not a separate algorithm.</p><h3 id="positivity-and-termination-move-to-the-checker" tabindex="-1">Positivity and termination move to the checker <a class="header-anchor" href="#positivity-and-termination-move-to-the-checker" aria-label="Permalink to “Positivity and termination move to the checker”">​</a></h3><p>Strict positivity is checked when the <code>data</code> declaration&#39;s ctor signatures are elaborated — the checker has the signatures, so it owns the check; the <code>desugar.data</code> native&#39;s positivity pass is retired (or kept only as an early-error mirror). Termination of <code>F.rec</code> uses the existing decreasing-argument metadata: <code>F.rec</code> is structurally decreasing on <code>v</code>&#39;s ctor spine by construction.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><code>desugar.data</code> (<code>engine-transform-rewrite/src/native/desugar.rs</code>) lowers <code>data Nat :: Zero | Succ(pred : Nat)</code> into a block of three kinds of bindings:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Removed</strong>: type-as-predicate arrows, <code>{&quot;tag&quot;}</code> string dispatch, the</li><li><strong>Kept</strong>: surface syntax (<code>data … :: … | …</code>), <code>match</code>/<code>absurd</code></li><li><strong>New capability</strong>: <code>F.rec</code> being dependent means *proofs by</li><li><strong>Migration</strong>: <code>lib-type</code> and consumers minting <code>{&quot;tag&quot;: …}</code> values</li><li><strong>Boundary</strong>: <code>data</code> declarations inside signatures erase at exec per</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0152-data-nominal-inductive-families.html"><code>design/0152-data-nominal-inductive-families.md</code></a>.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};